         border: 1px solid rgba(215, 223, 235, 0.8);
         border-radius: 24px;
         box-shadow: var(--shadow);
         backdrop-filter: blur(12px);
         padding: 32px;
       }

       .eyebrow {
         margin: 0 0 10px;
         color: var(--accent);
         font-size: 0.8rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0 0 12px;
         font-size: clamp(1.6rem, 3vw, 2.1rem);
         line-height: 1.1;
       }

       p {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .form {
         margin-top: 28px;
       }

       .form-field {
         display: flex;
         gap: 14px;
         align-items: flex-start;
         padding: 16px;
         border: 1px solid var(--border);
         border-radius: 16px;
         background: rgba(255, 255, 255, 0.85);
       }

       .checkbox {
         width: 20px;
         height: 20px;
         margin-top: 2px;
         accent-color: var(--accent);
         flex: 0 0 auto;
       }

       .field-copy {
         display: grid;
         gap: 4px;
       }

       .field-copy label {
         font-weight: 600;
         cursor: pointer;
       }

       .helper {
         font-size: 0.92rem;
       }

       .actions {
         margin-top: 20px;
       }

       .button {
         width: 100%;
         border: 0;
         border-radius: 14px;
         background: linear-gradient(135deg, var(--accent), #4f46e5);
         color: white;
         font: inherit;
         font-weight: 700;
         padding: 14px 18px;
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(37, 99, 235, 0.24);
         transition: transform 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
       }

       .button:hover {
         background: linear-gradient(135deg, var(--accent-hover), #4338ca);
         transform: translateY(-1px);
         box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
       }

       .button:focus-visible,
       .checkbox:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.25);
         outline-offset: 3px;
       }

       @media (max-width: 480px) {
         .card {
           padding: 24px;
           border-radius: 20px;
         }

         .form-field {
           padding: 14px;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const App = () => `
         <main class="card">
           <p class="eyebrow">Account setup</p>
           <h1>Terms of use consent</h1>
           <p>Please confirm that you agree to the terms before continuing.</p>

           <form class="form">
             ${ConsentField()}
             <div class="actions">
               ${PrimaryButton()}
             </div>
           </form>
         </main>
       `;

       const ConsentField = () => `
         <div class="form-field">
           <input
             class="checkbox"
             type="checkbox"
             id="terms"
             name="terms"
             required
           />
           <div class="field-copy">
             <label for="terms">I agree to the terms of use</label>
             <span class="helper">You must accept the terms to submit this form.</span>
           </div>
         </div>
       `;

       const PrimaryButton = () => `
         <button class="button" type="submit">Submit</button>
       `;

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

')
